namespace ghidra.app.plugin.core.compositeeditor;

using docking;
using ghidra.app.plugin.core.datamgr.util;
using ghidra.app.services;
using ghidra.program.model.data;

/**
 * Action for use in the composite data type editor.
 * This action has help associated with it.
 */
public class EditComponentAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Edit Component";
	private static string GROUP_NAME = BASIC_ACTION_GROUP;
	private static string DESCRIPTION = "Edit the selected component";
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };
	private static string[] MENU_PATH = new string[] { ACTION_NAME };
	private DataTypeManagerService dtmService;

	public EditComponentAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, MENU_PATH, null)
    {
		this.dtmService = provider.dtmService;
		setDescription(DESCRIPTION);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		int row = model.getRow();
		if (row >= model.getNumComponents()) {
			requestTableFocus();
			return;
		}

		if (!model.isEditComponentAllowed()) {
			model.setStatus("Can only edit a structure, union, enum or function-definition.");
			return;
		}

		DataTypeComponent comp = model.getComponent(row);
		DataType clickedType = comp.getDataType();
		DataType dt = DataTypeUtils.getBaseDataType(clickedType);
		edit(dt, clickedType.getName());
		requestTableFocus();
	}

	private void edit(DataType dt, string clickedName) {

		DataTypeManager dtm = model.getOriginalDataTypeManager();
		if (dtm == null) {
			// shouldn't happen
			model.setStatus("No Data Type Manager found for '" + clickedName + "'");
			return;
		}

		DataType actualType = dtm.getDataType(dt.getDataTypePath());
		if (actualType == null) {
			model.setStatus("Can't edit '" + dt.getDisplayName() + "' - type not found.");
			return;
		}

		dtmService.edit(actualType);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && model.isEditComponentAllowed();
	}

}
